create function pg_temp.seed_baseline(n integer) returns void language plpgsql as $$
declare f jsonb;m jsonb;obj jsonb;upload uuid;run uuid;snapshot uuid;begin
 select value->'baselines'->(n-1) into f from undo_fixture;m:=f->'manifest';
 upload:=('60000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid;run:=('70000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid;snapshot:=('a0000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid;
 insert into public.shop_devices(shop_device_id,shop_id,device_identifier,display_name,device_type,status)
  values((m->>'deviceId')::uuid,'10000000-0000-4000-8000-000000403019','SYNTHETIC-UNDO-'||n,'Synthetic Undo '||n,'pos','active');
 insert into public.payment_history_uploads(upload_id,shop_id,actor_kind,actor_id,object_key,file_name,file_sha256,byte_length,state,verified_at)
  values(upload,'10000000-0000-4000-8000-000000403019','pos_staff_manager','30000000-0000-4000-8000-000000403019','history/10000000-0000-4000-8000-000000403019/'||upload,'synthetic.zip',f->>'archiveSha256',1,'verified',clock_timestamp());
 insert into public.payment_history_migration_runs(run_id,shop_id,source_upload_id,actor_kind,actor_id,actor_session_id,request_key,request_digest,state,manifest,summary,receipt,source_mode,source_context)
  values(run,'10000000-0000-4000-8000-000000403019',upload,'pos_staff_manager','30000000-0000-4000-8000-000000403019','80000000-0000-4000-8000-000000403019',gen_random_uuid(),repeat('a',64),'applied',m,f->'summary',jsonb_build_object('source_snapshot_id',snapshot),'local_baseline_v2',
   jsonb_build_object('device_id',m->>'deviceId','local_dataset_id',m->>'localDatasetId','data_revision',m->>'dataRevision','restore_epoch',m->>'restoreEpoch','restore_lineage_id',m->>'restoreLineageId','writer_epoch','1'));
 insert into public.payment_history_source_snapshots(snapshot_id,shop_id,shop_device_id,local_dataset_id,data_revision,restore_epoch,archive_sha256,backup_sha256,source_manifest,source_summary,run_id,created_revision)
  values(snapshot,'10000000-0000-4000-8000-000000403019',(m->>'deviceId')::uuid,m->>'localDatasetId',(m->>'dataRevision')::bigint,0,f->>'archiveSha256',m->>'backupSha256',m,f->'summary',run,1);
 for obj in select value from jsonb_array_elements(f->'objects') loop
  insert into public.payment_history_source_objects(shop_id,source_snapshot_id,table_name,local_id,object_digest,original_object)
   values('10000000-0000-4000-8000-000000403019',snapshot,obj->>'table',case when obj->>'table'='operations' then (obj->>'line')::jsonb->>'operation_id' else (obj->>'line')::jsonb->>'id' end,
    encode(extensions.digest(convert_to(((obj->>'line')::jsonb)::text,'UTF8'),'sha256'),'hex'),(obj->>'line')::jsonb);
 end loop;
 perform app_private.payment_history_bind_local_baseline_v2('10000000-0000-4000-8000-000000403019',(m->>'deviceId')::uuid,snapshot,m->>'localDatasetId',(m->>'dataRevision')::bigint,0,(m->>'restoreLineageId')::uuid,1);
end;$$;
