 insert into public.payment_history_local_batch_map select '10000000-0000-4000-8000-000000403019','20000000-0000-4000-8000-000000403019',(select value#>>'{baselines,0,manifest,localDatasetId}' from undo_fixture),local_id,batch_id,object_digest
