create function pg_temp.stage_undo(label text,changes jsonb default '{}') returns uuid language plpgsql as $$
declare x jsonb;raw text;records jsonb;f jsonb;page jsonb;op uuid;fp text;hash text;root text;begin
 select c.value into x from undo_fixture u,jsonb_array_elements(u.value->'cases') c where c.value->>'name'=label;
 if x is null or x->>'kind'<>'Undo' then raise exception 'fixture_undo_missing';end if;
 op:=(x->>'operation_id')::uuid;fp:=x->>'request_fingerprint';root:=x->>'content_digest';
 if changes<>'{}'::jsonb then
  op:=gen_random_uuid();records:=((x->'pages'->0)->>'page_json')::jsonb;f:=(records->1->'fields')||changes;
  fp:=app_private.payment_history_field_hash_v1(array['historical-undo-request-v1',replace(op::text,'-',''),x->>'shop_id',x->>'local_dataset_id',f->>'batch_id',f->>'batch_revision',x->>'restore_epoch']);
  records:=jsonb_set(jsonb_set(jsonb_set(records,'{1,fields}',f),'{0,fields,operation_id}',to_jsonb(replace(op::text,'-',''))),'{0,fields,request_fingerprint}',to_jsonb(fp));
  raw:=records::text;hash:=encode(extensions.digest(convert_to(raw,'UTF8'),'sha256'),'hex');root:=encode(extensions.digest(convert_to(hash||chr(10),'UTF8'),'sha256'),'hex');
  x:=x||jsonb_build_object('pages',jsonb_build_array(jsonb_build_object('ordinal',1,'page_json',raw,'page_sha256',hash)));
 end if;
 perform app_private.payment_history_local_prepare_v2((x->>'shop_id')::uuid,(x->>'device_id')::uuid,jsonb_build_object('operation_id',op,'kind','Undo','local_dataset_id',x->>'local_dataset_id',
  'restore_epoch',x->>'restore_epoch','restore_lineage_id',x->>'restore_lineage_id','base_revision',x->>'base_revision','writer_epoch','1','request_fingerprint',fp,'content_digest',root,'page_count',1,'protocol_version',2));
 for page in select value from jsonb_array_elements(x->'pages') loop perform app_private.payment_history_local_stage_v2((x->>'shop_id')::uuid,(x->>'device_id')::uuid,page||jsonb_build_object('operation_id',op,'content_digest',root));end loop;
 return op;
end;$$;
create function pg_temp.review_undo(op uuid,ordinal integer default 1,token uuid default null,root text default null) returns jsonb language sql as $$
 select app_private.payment_history_local_review_undo_page_v2(p.shop_id,p.shop_device_id,p.operation_id,coalesce(root,p.content_digest),ordinal,token) from public.payment_history_local_publications p where p.operation_id=op;
$$;
select ok(not has_function_privilege('service_role','app_private.payment_history_local_review_undo_page_v2(uuid,uuid,uuid,text,integer,uuid)','EXECUTE'),'Undo review remains private before complete grant/delivery');
select ok(not has_function_privilege('authenticated','app_private.payment_history_local_review_undo_sources_v2(uuid,text)','EXECUTE'),'browser cannot supply an Undo provenance cursor');
select ok(not has_table_privilege('service_role','public.payment_history_local_review_undo_rows','INSERT'),'Undo ownership cache cannot be fabricated through table access');
select ok((select relrowsecurity from pg_class where oid='public.payment_history_local_review_undo_rows'::regclass),'Undo cache has RLS');
insert into undo_state select 'a',jsonb_build_object('operation_id',pg_temp.stage_undo('a-undo-baseline'));
insert into undo_state select 'a-review',pg_temp.review_undo((value->>'operation_id')::uuid) from undo_state where key='a';
select is((select value->>'state' from undo_state where key='a-review'),'reviewed','actual CLR Undo identifies its verified original baseline batch');
select is((select r.local_deactivated from public.payment_history_local_reviews r join undo_state s on r.operation_id=(s.value->>'operation_id')::uuid where s.key='a'),1,'baseline Undo deactivates one local row');
select is((select r.canonical_deactivated from public.payment_history_local_reviews r join undo_state s on r.operation_id=(s.value->>'operation_id')::uuid where s.key='a'),1,'baseline Undo owns exactly its canonical version');
select is((select r.local_gross::text from public.payment_history_local_reviews r join undo_state s on r.operation_id=(s.value->>'operation_id')::uuid where s.key='a'),'1200','local Undo gross agrees with actual CLR receipt');
select is((select r.canonical_gross::text from public.payment_history_local_reviews r join undo_state s on r.operation_id=(s.value->>'operation_id')::uuid where s.key='a'),'1200','canonical Undo gross is separately computed');
select is((select x.baseline_local_id from public.payment_history_local_review_undo_rows x join undo_state s on x.operation_id=(s.value->>'operation_id')::uuid where s.key='a'),'1','baseline row identity is preserved as source provenance');
select is((select pg_temp.review_undo((value->>'operation_id')::uuid) from undo_state where key='a'),(select value from undo_state where key='a-review'),'lost first review ACK recovers the same immutable decision token');
select is((select count(*) from public.payment_history_local_review_undo_rows),1::bigint,'review replay does not append a second source row');
select throws_ok($$select pg_temp.review_undo((value->>'operation_id')::uuid,token=>gen_random_uuid()) from undo_state where key='a'$$,'40001','payment_history_local_review_stale','another token cannot reuse the review');
select throws_ok($$select pg_temp.review_undo((value->>'operation_id')::uuid,root=>repeat('f',64)) from undo_state where key='a'$$,'40001','payment_history_local_review_stale','Undo root cannot be switched');
select is((select active from public.payment_history_movement_versions where movement_version_id='e1000000-0000-4000-8000-000000403019'),true,'private review has no financial deactivation');
insert into undo_state select 'wrong-batch',jsonb_build_object('operation_id',pg_temp.stage_undo('a-undo-baseline','{"batch_id":"foreign-batch"}'));
select throws_ok($$select pg_temp.review_undo((value->>'operation_id')::uuid) from undo_state where key='wrong-batch'$$,'40001','payment_history_local_undo_owner_unverified','another batch is denied even with a correctly bound root');
update public.payment_history_local_publications set state='aborted' where operation_id=(select (value->>'operation_id')::uuid from undo_state where key='wrong-batch');
insert into undo_state select 'wrong-apply',jsonb_build_object('operation_id',pg_temp.stage_undo('a-undo-baseline','{"apply_operation_id":"f0000000-0000-4000-8000-000000403019"}'));
select throws_ok($$select pg_temp.review_undo((value->>'operation_id')::uuid) from undo_state where key='wrong-apply'$$,'40001','payment_history_local_undo_owner_unverified','another Apply cannot own the local batch');
update public.payment_history_local_publications set state='aborted' where operation_id=(select (value->>'operation_id')::uuid from undo_state where key='wrong-apply');
insert into undo_state select 'wrong-revision',jsonb_build_object('operation_id',pg_temp.stage_undo('a-undo-baseline','{"batch_revision":"2"}'));
select throws_ok($$select pg_temp.review_undo((value->>'operation_id')::uuid) from undo_state where key='wrong-revision'$$,'40001','payment_history_local_undo_owner_unverified','local batch revision is verified independently of data revision');
update public.payment_history_local_publications set state='aborted' where operation_id=(select (value->>'operation_id')::uuid from undo_state where key='wrong-revision');
-- The following admitted Apply states are explicit component fixtures. Their
-- pages/receipts are original CLR bytes; this does not prove HTTP delivery.
create function pg_temp.seed_apply(label text,owns boolean,seq bigint) returns uuid language plpgsql as $$
declare x jsonb;receipt jsonb;page jsonb;rec record;f jsonb;t jsonb;e jsonb;version uuid;batch uuid:=gen_random_uuid();other_batch uuid;
 op uuid;movement_no integer:=0;binding_page integer;binding_record integer;scope text;source_hash text;begin
 select c.value into x from undo_fixture u,jsonb_array_elements(u.value->'cases') c where c.value->>'name'=label;op:=(x->>'operation_id')::uuid;receipt:=(x->>'local_receipt_json')::jsonb;
 insert into public.payment_history_batches(batch_id,shop_id,origin,apply_operation_id,created_revision) values(batch,'10000000-0000-4000-8000-000000403019','local_migration',op,1);
 if not owns then
  update public.payment_history_movement_versions set active=false where shop_id='10000000-0000-4000-8000-000000403019' and active;
  other_batch:=gen_random_uuid();insert into public.payment_history_batches(batch_id,shop_id,origin,apply_operation_id,created_revision) values(other_batch,'10000000-0000-4000-8000-000000403019','local_migration',gen_random_uuid(),1);
 else other_batch:=batch;end if;
 insert into public.payment_history_local_publications(operation_id,shop_id,shop_device_id,server_dataset_id,local_dataset_id,restore_lineage_id,restore_epoch,writer_epoch,operation_kind,request_fingerprint,content_digest,protocol_version,base_revision,page_count,staged_pages,state,grant_id,authorization_staff_id,authorization_credential_version,issued_at,expires_at,local_sequence,local_revision,local_batch_id,local_receipt_json,server_receipt)
  select op,r.shop_id,(x->>'device_id')::uuid,r.dataset_id,x->>'local_dataset_id',(x->>'restore_lineage_id')::uuid,0,1,'Apply',x->>'request_fingerprint',x->>'content_digest',2,(x->>'base_revision')::bigint,(x->>'page_count')::integer,(x->>'page_count')::integer,'committed',gen_random_uuid(),'30000000-0000-4000-8000-000000403019',1,clock_timestamp(),clock_timestamp()+interval '30 seconds',seq,(x->>'base_revision')::bigint+(receipt->>'InsertedCount')::bigint,receipt->>'BatchId',x->>'local_receipt_json',jsonb_build_object('batch_id',batch)
  from public.payment_history_runtime r where shop_id='10000000-0000-4000-8000-000000403019';
 for page in select value from jsonb_array_elements(x->'pages') loop
  perform app_private.payment_history_local_page_v2(page->>'page_json');
  insert into public.payment_history_local_publication_pages values('10000000-0000-4000-8000-000000403019',op,(page->>'ordinal')::integer,page->>'page_json',page->>'page_sha256');
  for rec in select value v,ordinality n from jsonb_array_elements((page->>'page_json')::jsonb) with ordinality loop
   if rec.v->>'kind'='binding' then binding_page:=(page->>'ordinal')::integer;binding_record:=rec.n::integer;scope:=rec.v#>>'{fields,local_scope_id}';
   elsif rec.v->>'kind'='file' then source_hash:=rec.v#>>'{fields,sha256}';
   elsif rec.v->>'kind'='movement' then
    f:=rec.v->'fields';t:=app_private.payment_history_local_transaction_v2(f,source_hash);e:=app_private.payment_history_economics_v1(t);movement_no:=movement_no+1;version:=gen_random_uuid();
    insert into public.payment_history_movement_versions(movement_version_id,shop_id,merchant_id,external_namespace,external_id,identity_key,economic_digest,business_ticks,business_date,gross_clp,commission_clp,commission_vat_clp,net_clp,movement_kind,transaction_state,transaction,owner_batch_id,created_revision)
     values(version,'10000000-0000-4000-8000-000000403019','c0000000-0000-4000-8000-000000403019',t->>'externalNamespace',t->>'externalId',
      encode(extensions.digest(convert_to('10000000-0000-4000-8000-000000403019'||chr(31)||'getnet'||chr(31)||'c0000000-0000-4000-8000-000000403019'||chr(31)||(t->>'externalNamespace')||chr(31)||(t->>'externalId'),'UTF8'),'sha256'),'hex'),
      app_private.payment_history_economic_digest_v1(e),(e->>'businessTicks')::bigint,'2024-02-01',(e->>'grossClp')::bigint,(e->>'commissionClp')::bigint,null,(e->>'netClp')::bigint,'Sale','ABONADO',t,other_batch,1);
    insert into public.payment_history_local_publication_map values('10000000-0000-4000-8000-000000403019',op,movement_no,version,owns,true,scope,t->>'externalNamespace',t->>'externalId',(page->>'ordinal')::integer,rec.n::integer,binding_page,binding_record);
   end if;
  end loop;
 end loop;
 if movement_no<>(receipt->>'InsertedCount')::integer then raise exception 'fixture_source_count_mismatch';end if;
 update public.payment_history_local_writer_contexts set local_revision=(x->>'base_revision')::bigint+movement_no where shop_id='10000000-0000-4000-8000-000000403019' and shop_device_id=(x->>'device_id')::uuid;
 update public.payment_history_runtime set revision=revision+1 where shop_id='10000000-0000-4000-8000-000000403019';
 return op;
end;$$;
do $$begin perform pg_temp.seed_apply('b-locally-new-canonical-existing',false,7);end;$$;
select throws_ok($$select pg_temp.review_undo((value->>'operation_id')::uuid) from undo_state where key='a'$$,'40001','payment_history_local_review_stale','changed canonical revision invalidates the old review');
insert into undo_state select 'b',jsonb_build_object('operation_id',pg_temp.stage_undo('b-undo-local-canonical-duplicate'));
insert into undo_state select 'b-review',pg_temp.review_undo((value->>'operation_id')::uuid) from undo_state where key='b';
select is((select value->>'state' from undo_state where key='b-review'),'reviewed','actual POS B Undo follows its committed original Apply');
select is((select r.local_deactivated from public.payment_history_local_reviews r join undo_state s on r.operation_id=(s.value->>'operation_id')::uuid where s.key='b'),1,'POS B deactivates its own local insert');
select is((select r.canonical_deactivated from public.payment_history_local_reviews r join undo_state s on r.operation_id=(s.value->>'operation_id')::uuid where s.key='b'),0,'canonical duplicate confers no Undo ownership');
select is((select r.local_gross::text from public.payment_history_local_reviews r join undo_state s on r.operation_id=(s.value->>'operation_id')::uuid where s.key='b'),'1500','POS B local amount agrees with actual CLR Undo receipt');
select is((select r.canonical_gross::text from public.payment_history_local_reviews r join undo_state s on r.operation_id=(s.value->>'operation_id')::uuid where s.key='b'),'0','another canonical batch loses no amount');
select ok((select not x.canonical_owned from public.payment_history_local_review_undo_rows x join undo_state s on x.operation_id=(s.value->>'operation_id')::uuid where s.key='b'),'cached row retains the duplicate ownership boundary');
do $$begin perform pg_temp.seed_apply('c-apply-201',true,9);end;$$;
insert into undo_state select 'c',jsonb_build_object('operation_id',pg_temp.stage_undo('c-undo-201'));
insert into undo_state select 'c-review',pg_temp.review_undo((value->>'operation_id')::uuid) from undo_state where key='c';
select is((select value->>'state' from undo_state where key='c-review'),'reviewing','201 real local rows require more than one review request');
select is((select value->>'next_ordinal' from undo_state where key='c-review'),'2','review cursor advances exactly one bounded page');
select is((select r.local_deactivated from public.payment_history_local_reviews r join undo_state s on r.operation_id=(s.value->>'operation_id')::uuid where s.key='c'),200,'first request classifies no more than200 rows');
select is((select count(*) from public.payment_history_local_review_undo_rows x join undo_state s on x.operation_id=(s.value->>'operation_id')::uuid where s.key='c'),200::bigint,'first cursor owns exactly200 source coordinates');
select is((select pg_temp.review_undo((value->>'operation_id')::uuid) from undo_state where key='c'),(select value from undo_state where key='c-review'),'lost ACK of page1 does not advance the cursor or count twice');
insert into undo_state select 'c-final',pg_temp.review_undo((value->>'operation_id')::uuid,2,(select (value->>'review_token')::uuid from undo_state where key='c-review')) from undo_state where key='c';
select is((select value->>'state' from undo_state where key='c-final'),'reviewed','second bounded request completes the actual201-row Undo');
select is((select r.local_deactivated from public.payment_history_local_reviews r join undo_state s on r.operation_id=(s.value->>'operation_id')::uuid where s.key='c'),201,'all local rows classified once');
select is((select r.canonical_deactivated from public.payment_history_local_reviews r join undo_state s on r.operation_id=(s.value->>'operation_id')::uuid where s.key='c'),201,'only the201 owned canonical versions are selected');
select is((select r.local_gross::text from public.payment_history_local_reviews r join undo_state s on r.operation_id=(s.value->>'operation_id')::uuid where s.key='c'),'301500','bounded local sum agrees with actual CLR Undo receipt');
select is((select r.canonical_gross::text from public.payment_history_local_reviews r join undo_state s on r.operation_id=(s.value->>'operation_id')::uuid where s.key='c'),'301500','canonical sum agrees independently for the owned batch');
select is((select count(*) from public.payment_history_local_review_undo_rows x join undo_state s on x.operation_id=(s.value->>'operation_id')::uuid where s.key='c'),201::bigint,'cursor crosses original Apply page boundaries without duplicate coordinates');
select is((select count(*) from public.payment_history_movement_versions where shop_id='10000000-0000-4000-8000-000000403019' and active),202::bigint,'review does not deactivate the201 owned or the other canonical version');
